UPDATE teamup_demand_detail
SET current_members = COALESCE(current_members, 0) + 1
WHERE demand_uuid = #{demand_uuid}

UPDATE demand_application
SET status = 'EXPIRED',
    update_time = NOW()
WHERE demand_uuid = #{demand_uuid}
  AND uuid != #{accepted_uuid}
  AND status = 'PENDING'

