DELETE FROM demand_favorite
WHERE user_uuid = #{user_uuid}
  AND demand_uuid = #{demand_uuid}

mapper.select:

WHERE d.taker_uuid = #{user_uuid}
   OR EXISTS (
       SELECT 1
       FROM demand_application da
       WHERE da.demand_uuid = d.uuid
         AND da.applicant_uuid = #{user_uuid}
         AND da.status = 'ACCEPTED'
   )
ORDER BY d.update_time DESC


INNER JOIN demand_favorite df ON d.uuid = df.demand_uuid
WHERE df.user_uuid = #{user_uuid}
ORDER BY df.create_time DESC


WHERE da.demand_uuid = #{demand_uuid}
